import { Platform } from 'react-native'
import { requireOptionalNativeModule } from 'expo-modules-core'
import { GarminCommand } from './protocol'
import {
  GarminLinkEvent,
  GarminLinkListener,
  GarminTransport,
} from './transport'

/**
 * The real Connect IQ link.
 *
 * The native half is the local Expo module in `modules/treemapper-garmin/`,
 * which wraps `com.garmin.connectiq:ciq-companion-app-sdk`. It is a local
 * module rather than an edit to `android/` because that folder is gitignored
 * and regenerated by `expo prebuild`, so a hand edit there would not survive.
 *
 * **Both platforms.** The same module carries a Kotlin half wrapping
 * `com.garmin.connectiq:ciq-companion-app-sdk` and a Swift half wrapping the
 * Connect IQ Mobile SDK for iOS, vendored as an xcframework. They emit the
 * same events, so there is one state machine above them, with one difference
 * that reaches this far: iOS cannot read the paired device list and has to ask
 * the user through Garmin Connect, which is the `needs_device` blocker and
 * `chooseDevice`.
 *
 * Nothing here parses anything. The native side emits the payload raw and the
 * parser lives in `protocol.ts`, shared with the mock, so there is exactly one
 * place where a wire format change has to be understood.
 */

const NATIVE_MODULE_NAME = 'TreeMapperGarmin'
const NATIVE_EVENT_NAME = 'GarminLinkEvent'

interface GarminNativeModule {
  /**
   * @param tethered talk to the Connect IQ simulator over ADB instead of to a
   *   real device. Android and development only; a release build ignores it,
   *   and so does iOS, where the SDK owns the Bluetooth link itself and there
   *   is no simulator transport to speak to. See the module's README for the
   *   startup order, which matters.
   */
  start(tethered?: boolean): void
  stop(): void
  send(command: GarminCommand): void
  openWatchApp(): void
  openStore(): void
  chooseDevice(): void
  addListener(
    event: string,
    handler: (payload: GarminLinkEvent) => void,
  ): { remove: () => void }
}

const nativeModule =
  requireOptionalNativeModule<GarminNativeModule>(NATIVE_MODULE_NAME)

/** True once the native module ships for this platform. Nothing else should test for it. */
export const hasNativeGarminLink = (): boolean =>
  !!nativeModule && (Platform.OS === 'android' || Platform.OS === 'ios')

/**
 * Speak to the Connect IQ simulator over ADB rather than to a real device.
 *
 * Off by default, and ignored entirely in a release build. Turning it on is
 * how the native module gets exercised without a Garmin in the room:
 *
 *   1. `adb forward tcp:7381 tcp:7381`
 *   2. open the capture screen, so the phone is listening
 *   3. Connection > Start in the Connect IQ simulator
 *
 * The order matters. The simulator dials in to a socket the phone has to be
 * holding open already.
 *
 * Set `EXPO_PUBLIC_GARMIN_TETHERED=true` in `.env` to turn it on for a dev
 * build. Expo inlines that value at bundle time, so Metro needs a restart with
 * a cleared cache before a change to it takes effect. `setGarminTetheredMode`
 * still overrides it at runtime, as long as it runs before the capture screen
 * opens and calls `start`.
 */
let useTethered =
  __DEV__ && process.env.EXPO_PUBLIC_GARMIN_TETHERED === 'true'

export const setGarminTetheredMode = (next: boolean) => {
  useTethered = next
}

export const getGarminTetheredMode = (): boolean => useTethered

export const createNativeTransport = (): GarminTransport | null => {
  if (!nativeModule || !hasNativeGarminLink()) {
    return null
  }

  let subscription: { remove: () => void } | null = null

  return {
    name: 'connect-iq',

    start(listener: GarminLinkListener) {
      // Listen before starting. The native side emits its first log lines
      // from inside initialize(), and a dropped "SDK init failed" is the one
      // message that explains an otherwise silent screen.
      subscription = nativeModule.addListener(NATIVE_EVENT_NAME, listener)
      nativeModule.start(useTethered && Platform.OS === 'android')
    },

    stop() {
      subscription?.remove()
      subscription = null
      nativeModule.stop()
    },

    send(command: GarminCommand) {
      nativeModule.send(command)
    },

    openWatchApp() {
      nativeModule.openWatchApp()
    },

    openStore() {
      nativeModule.openStore()
    },

    chooseDevice() {
      nativeModule.chooseDevice()
    },
  }
}
